/**
 * Generates TypeScript declaration files (.d.ts) for the notehub-js library.
 *
 * The library is auto-generated by openapi-generator (javascript generator), which
 * does not emit TypeScript types. Rather than re-deriving types from the OpenAPI spec
 * (and having to replicate the generator's model-naming logic), this script parses the
 * ALREADY-generated JavaScript in `src/src` — the exact runtime surface — and emits a
 * matching `.d.ts` beside each `.js` file. Because it consumes the generated output, the
 * declarations stay in lockstep with the code on every release.
 *
 * Run after `generateDocs` (see root package.json `generateTypes` script).
 */

const fs = require("fs");
const path = require("path");

const SRC = path.join(__dirname, "..", "..", "src", "src");
const MODEL_DIR = path.join(SRC, "model");
const API_DIR = path.join(SRC, "api");

const HEADER = `/**
 * Notehub API - TypeScript definitions
 *
 * NOTE: This file is auto-generated by .github/scripts/generate-types.js from the
 * generated JavaScript sources. Do not edit it manually.
 */

`;

/** Map a JSDoc type expression (e.g. "Array.<module:model/Event>") to a TS type. */
function jsdocToTs(raw, ctx) {
  const type = (raw || "").trim();
  const refs = (ctx && ctx.refs) || new Set();
  const selfClass = ctx && ctx.selfClass;
  const nestedEnums = (ctx && ctx.nestedEnums) || {};
  const oneOfMembers = (ctx && ctx.oneOfMembers) || null;

  if (!type) return "any";

  // Array.<INNER>
  let m = type.match(/^Array\.<(.+)>$/);
  if (m) return `${jsdocToTs(m[1], ctx)}[]`;

  // Object.<K, V> (map). Fall back to `any` values when V is a nested object literal.
  m = type.match(/^Object\.<\s*[^,]+,\s*(.+)>$/);
  if (m) {
    const valRaw = m[1].trim();
    const val = valRaw.startsWith("{") ? "any" : jsdocToTs(valRaw, ctx);
    return `{ [key: string]: ${val} }`;
  }

  // module:model/X  or  module:model/X.SomeEnum (inline enum reference)
  m = type.match(/^module:model\/([A-Za-z0-9_]+)(?:\.([A-Za-z0-9_]+))?$/);
  if (m) {
    const modelName = m[1];
    const enumName = m[2];
    // openapi-generator sometimes emits primitives as module:model/String etc.
    const primitive = mapPrimitive(modelName);
    if (!enumName && primitive) return primitive;
    if (enumName) {
      const union = (values) =>
        values.map((v) => JSON.stringify(v)).join(" | ");
      // 1. Same class with a local enum definition.
      if (modelName === selfClass && nestedEnums[enumName])
        return union(nestedEnums[enumName]);
      // 2. The referenced class defines the enum in its own file.
      const other = nestedEnumsOf(modelName);
      if (other[enumName]) return union(other[enumName]);
      // 3. oneOf: the enum is synthesized on the wrapper but really lives on the
      //    variants — union the same-named enum across the oneOf member types.
      if (oneOfMembers) {
        const values = [];
        for (const member of oneOfMembers) {
          const memberEnums = nestedEnumsOf(member);
          if (memberEnums[enumName]) {
            for (const v of memberEnums[enumName])
              if (!values.includes(v)) values.push(v);
          }
        }
        if (values.length) return union(values);
      }
      return "string"; // unresolved inline enum: keep loose but safe
    }
    refs.add(modelName);
    return modelName;
  }

  // module:ApiClient
  if (type === "module:ApiClient") {
    refs.add("ApiClient");
    return "ApiClient";
  }

  const prim = mapPrimitive(type);
  return prim || "any";
}

function mapPrimitive(t) {
  switch (t) {
    case "String":
      return "string";
    case "Number":
      return "number";
    case "Boolean":
      return "boolean";
    case "Date":
      return "Date";
    case "Object":
      return "{ [key: string]: any }";
    case "Blob":
      return "Blob";
    case "File":
      return "File";
    default:
      return null;
  }
}

/** Map a `let returnType = X;` expression to a TS type. */
function returnTypeToTs(expr, refs) {
  const t = (expr || "").trim().replace(/;$/, "");
  if (!t || t === "null") return "void";
  let m = t.match(/^\[(.+)\]$/);
  if (m) return `${returnTypeToTs(m[1], refs)}[]`;
  if (/^['"].*['"]$/.test(t)) {
    const inner = t.slice(1, -1);
    return mapPrimitive(inner) || "any";
  }
  const prim = mapPrimitive(t);
  if (prim) return prim;
  if (/^[A-Za-z0-9_]+$/.test(t)) {
    refs.add(t);
    return t;
  }
  return "any";
}

/** Emit `import X from "./X";` lines for referenced model/ApiClient names. */
function importBlock(refs, selfName, fromDir) {
  const lines = [];
  Array.from(refs)
    .filter((r) => r && r !== selfName)
    .sort()
    .forEach((r) => {
      const rel =
        r === "ApiClient" ? `${fromDir}ApiClient` : `${fromDir}model/${r}`;
      lines.push(`import ${r} from "${rel}";`);
    });
  return lines.length ? lines.join("\n") + "\n\n" : "";
}

// ---------------------------------------------------------------------------
// Models
// ---------------------------------------------------------------------------

function isEnumClass(js) {
  // Enum classes have bare `name = "value";` const members and no `static initialize`.
  return (
    /^\s{2}[A-Za-z0-9_]+ = "(?:[^"\\]|\\.)*";/m.test(js) &&
    !/static initialize/.test(js)
  );
}

function parseNestedEnums(js, className) {
  // ClassName["XxxEnum"] = { key: "value", ... };
  const enums = {};
  const re = new RegExp(
    `${escapeRe(className)}\\["([A-Za-z0-9_]+)"\\]\\s*=\\s*\\{([\\s\\S]*?)\\n\\};`,
    "g",
  );
  let m;
  while ((m = re.exec(js))) {
    const name = m[1];
    const body = m[2];
    const values = [];
    // Match real entries (`  key: "value",`) only — skip JSDoc `* value: "..."` comment lines.
    for (const line of body.split("\n")) {
      const vm = line.match(
        /^\s*[A-Za-z0-9_]+:\s*("(?:[^"\\]|\\.)*"|\d+(?:\.\d+)?),?\s*$/,
      );
      if (!vm) continue;
      const raw = vm[1];
      const val = raw.startsWith('"') ? JSON.parse(raw) : Number(raw);
      if (!values.includes(val)) values.push(val);
    }
    enums[name] = values;
  }
  return enums;
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Nested enums of another model, read from its .js file (memoized). Used to resolve
// cross-class inline enum references (e.g. `module:model/Monitor.SourceTypeEnum`).
const _nestedEnumCache = {};
function nestedEnumsOf(modelName) {
  if (!(modelName in _nestedEnumCache)) {
    const file = path.join(MODEL_DIR, `${modelName}.js`);
    _nestedEnumCache[modelName] = fs.existsSync(file)
      ? parseNestedEnums(fs.readFileSync(file, "utf8"), modelName)
      : {};
  }
  return _nestedEnumCache[modelName];
}

// Map each property to its JSDoc @member type, binding the type to the assignment that
// targets THIS class. Models generated from an allOf/interface (e.g. CreateMonitor) also
// contain an "Implement <Interface> interface" block with `Interface.prototype[...]`
// assignments; binding to the self class avoids picking up those cross-class types.
function memberTypeMap(js, className) {
  const map = {};
  // @member line, then any further JSDoc lines (e.g. `@default`), then the closing `*/`
  // and the prototype assignment it documents. Bind the type only when the assignment
  // targets THIS class (see comment above).
  const re =
    /@member \{([^}]+)\}\s+[A-Za-z0-9_]+[^\n]*\n(?:\s*\*[^\n]*\n)*?\s*\*\/\s*\n\s*([A-Za-z0-9_]+)\.prototype\["([^"]+)"\]/g;
  let m;
  while ((m = re.exec(js))) {
    if (m[2] === className) map[m[3]] = m[1].trim();
  }
  return map;
}

// Property names in declaration order, from this class's prototype assignments.
function propList(js, className) {
  const props = [];
  const seen = new Set();
  const re = new RegExp(
    `${escapeRe(className)}\\.prototype\\["([^"]+)"\\]`,
    "g",
  );
  let m;
  while ((m = re.exec(js))) {
    if (!seen.has(m[1])) {
      seen.add(m[1]);
      props.push(m[1]);
    }
  }
  return props;
}

function requiredSet(js, className) {
  const required = new Set();
  const block = js.match(
    new RegExp(
      `${escapeRe(className)}\\.RequiredProperties\\s*=\\s*\\[([\\s\\S]*?)\\];`,
    ),
  );
  if (block) {
    const re = /"((?:[^"\\]|\\.)*)"/g;
    let m;
    while ((m = re.exec(block[1]))) required.add(m[1]);
  }
  return required;
}

// TS property declaration lines for a model/oneOf's flattened members.
function propLines(js, className, ctx) {
  const typeByName = memberTypeMap(js, className);
  const required = requiredSet(js, className);
  return propList(js, className).map((name) => {
    const tsType = jsdocToTs(typeByName[name], ctx);
    const opt = required.has(name) ? "" : "?";
    return `  ${JSON.stringify(name)}${opt}: ${tsType};`;
  });
}

// Static enum members (`static readonly XxxEnum: { ... }`) for a model's nested enums.
function enumMemberLines(nestedEnums) {
  return Object.entries(nestedEnums).map(([enumName, values]) => {
    const shape = values.map(
      (v) => `${JSON.stringify(String(v))}: ${JSON.stringify(v)}`,
    );
    return `  static readonly ${enumName}: { ${shape.join("; ")} };`;
  });
}

// oneOf wrapper models declare `ClassName.OneOf = [...]`; return the member class names.
function parseOneOf(js, className) {
  const m = js.match(
    new RegExp(`${escapeRe(className)}\\.OneOf\\s*=\\s*\\[([\\s\\S]*?)\\];`),
  );
  if (!m) return null;
  const members = [];
  const re = /"([A-Za-z0-9_]+)"/g;
  let x;
  while ((x = re.exec(m[1]))) members.push(x[1]);
  return members;
}

function generateOneOf(className, js, members) {
  const refs = new Set(members);
  const nestedEnums = parseNestedEnums(js, className);
  const ctx = {
    refs,
    selfClass: className,
    nestedEnums,
    oneOfMembers: members,
  };
  const union = members.join(" | ");
  const lines = propLines(js, className, ctx);
  const enumLines = enumMemberLines(nestedEnums);

  let body = "";
  body += `  constructor(instance?: ${union} | null);\n\n`;
  body += `  actualInstance: ${union} | null;\n`;
  body += `  getActualInstance(): ${union} | null;\n`;
  body += `  setActualInstance(obj: ${union}): void;\n`;
  body += `  toJSON(): ${union} | null;\n`;
  body += `  static fromJSON(jsonString: string): ${className};\n`;
  body += `  static constructFromObject(data: any, obj?: ${className}): ${className};\n`;
  if (lines.length) {
    body +=
      `\n  // Convenience members flattened from the oneOf variants (present on the prototype):\n` +
      lines.join("\n") +
      "\n";
  }
  if (enumLines.length) body += `\n` + enumLines.join("\n") + "\n";

  return (
    HEADER +
    importBlock(refs, className, "../") +
    `declare class ${className} {\n${body}}\n\n` +
    `export default ${className};\n`
  );
}

function generateEnumClass(className, js) {
  const members = [];
  const re = /^\s{2}([A-Za-z0-9_]+) = ("(?:[^"\\]|\\.)*"|\d+(?:\.\d+)?);/gm;
  let m;
  while ((m = re.exec(js))) {
    const name = m[1];
    const val = m[2];
    members.push(`  static readonly ${JSON.stringify(name)}: ${val};`);
  }
  return (
    HEADER +
    `declare class ${className} {\n${members.join("\n")}\n\n` +
    `  static constructFromObject(object: any): ${className};\n}\n\n` +
    `export default ${className};\n`
  );
}

function generateModel(className, js) {
  if (isEnumClass(js)) return generateEnumClass(className, js);

  const oneOf = parseOneOf(js, className);
  if (oneOf) return generateOneOf(className, js, oneOf);

  const refs = new Set();
  const nestedEnums = parseNestedEnums(js, className);
  const ctx = { refs, selfClass: className, nestedEnums };

  const lines = propLines(js, className, ctx);
  const enumLines = enumMemberLines(nestedEnums);
  const hasValidate = /static validateJSON\(/.test(js);

  let body = "";
  if (lines.length) body += lines.join("\n") + "\n";
  if (enumLines.length)
    body += (body ? "\n" : "") + enumLines.join("\n") + "\n";
  body += `${body ? "\n" : ""}  static constructFromObject(data: any, obj?: ${className}): ${className};\n`;
  if (hasValidate) body += `  static validateJSON(data: any): boolean;\n`;

  return (
    HEADER +
    importBlock(refs, className, "../") +
    `declare class ${className} {\n${body}}\n\n` +
    `export default ${className};\n`
  );
}

// ---------------------------------------------------------------------------
// APIs
// ---------------------------------------------------------------------------

function generateApi(className, js) {
  const refs = new Set(["ApiClient"]);

  // baseMethodName -> returnType expression, taken from the *WithHttpInfo variant.
  const returnByBase = {};
  const rtRe =
    /([A-Za-z0-9_]+)WithHttpInfo\s*\([^)]*\)\s*\{[\s\S]*?let returnType = ([^;]+);/g;
  let rm;
  while ((rm = rtRe.exec(js))) returnByBase[rm[1]] = rm[2].trim();

  // Each JSDoc block immediately followed by `name(args) {`
  const methods = [];
  const methodRe =
    /\/\*\*([\s\S]*?)\*\/\s*\n\s*([A-Za-z0-9_]+)\s*\(([^)]*)\)\s*\{/g;
  let m;
  while ((m = methodRe.exec(js))) {
    const jsdoc = m[1];
    const name = m[2];
    const argList = m[3];
    if (name === "constructor") continue;

    const args = argList
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    // @param {Type} name   (name may be "opts.field")
    const paramTypes = {};
    const pRe = /@param \{([^}]+)\}\s+\[?([A-Za-z0-9_.]+)\]?/g;
    let pm;
    while ((pm = pRe.exec(jsdoc))) paramTypes[pm[2]] = pm[1];

    const sigParts = [];
    for (const arg of args) {
      if (arg === "opts") {
        const fields = Object.keys(paramTypes)
          .filter((k) => k.startsWith("opts."))
          .map((k) => {
            const field = k.slice("opts.".length);
            const t = jsdocToTs(paramTypes[k], { refs });
            return `${JSON.stringify(field)}?: ${t}`;
          });
        sigParts.push(`opts?: { ${fields.join("; ")} }`);
      } else {
        const t = jsdocToTs(paramTypes[arg], { refs });
        sigParts.push(`${arg}: ${t}`);
      }
    }

    const base = name.endsWith("WithHttpInfo")
      ? name.slice(0, -"WithHttpInfo".length)
      : name;
    const rt = returnTypeToTs(returnByBase[base], refs);
    const ret = name.endsWith("WithHttpInfo")
      ? `Promise<{ data: ${rt}; response: unknown }>`
      : `Promise<${rt}>`;

    methods.push(`  ${name}(${sigParts.join(", ")}): ${ret};`);
  }

  return (
    HEADER +
    importBlock(refs, className, "../") +
    `declare class ${className} {\n` +
    `  constructor(apiClient?: ApiClient);\n\n` +
    methods.join("\n\n") +
    `\n}\n\n` +
    `export default ${className};\n`
  );
}

// ---------------------------------------------------------------------------
// ApiClient (stable public surface — authored, not derived)
// ---------------------------------------------------------------------------

const API_CLIENT_DTS =
  HEADER +
  `type Authentication = {
  type?: string;
  username?: string;
  password?: string;
  apiKey?: string;
  apiKeyPrefix?: string;
  accessToken?: string;
  [key: string]: any;
};

declare class ApiClient {
  constructor(basePath?: string);

  static instance: ApiClient;

  basePath: string;
  authentications: { [name: string]: Authentication };
  defaultHeaders: { [name: string]: string };
  timeout: number;
  cache: boolean;
  enableCookies: boolean;
  requestAgent: any;
  plugins: any;

  paramToString(param: any): string;
  buildUrl(path: string, pathParams: object, apiBasePath?: string): string;
  isJsonMime(contentType: string): boolean;
  jsonPreferredMime(contentTypes: string[]): string | null;
  isFileParam(param: any): boolean;
  normalizeParams(params: object): object;
  buildCollectionParam(param: any[], collectionFormat: string): any;
  applyAuthToRequest(request: any, authNames: string[]): void;
  deserialize(response: any, returnType: any): any;
  callApi(
    path: string,
    httpMethod: string,
    pathParams: object,
    queryParams: object,
    headerParams: object,
    formParams: object,
    bodyParam: any,
    authNames: string[],
    contentTypes: string[],
    accepts: string[],
    returnType: any,
    apiBasePath?: string
  ): Promise<any>;

  static convertToType(data: any, type: any): any;

  static CollectionFormatEnum: {
    CSV: ",";
    SSV: " ";
    TSV: "\\t";
    PIPES: "|";
    MULTI: "multi";
  };
}

export default ApiClient;
`;

// ---------------------------------------------------------------------------
// index.d.ts (mirror the runtime named exports)
// ---------------------------------------------------------------------------

function generateIndex(indexJs) {
  const re = /^import\s+([A-Za-z0-9_]+)\s+from\s+"(\.[^"]+)";/gm;
  const lines = [HEADER.trimEnd() + "\n"];
  let m;
  while ((m = re.exec(indexJs))) {
    lines.push(`export { default as ${m[1]} } from "${m[2]}";`);
  }
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// Driver
// ---------------------------------------------------------------------------

function processDir(dir, generator) {
  let count = 0;
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith(".js")) continue;
    const className = file.replace(/\.js$/, "");
    const js = fs.readFileSync(path.join(dir, file), "utf8");
    const dts = generator(className, js);
    fs.writeFileSync(path.join(dir, `${className}.d.ts`), dts);
    count++;
  }
  return count;
}

function main() {
  const models = processDir(MODEL_DIR, generateModel);
  const apis = processDir(API_DIR, generateApi);
  fs.writeFileSync(path.join(SRC, "ApiClient.d.ts"), API_CLIENT_DTS);
  const indexJs = fs.readFileSync(path.join(SRC, "index.js"), "utf8");
  fs.writeFileSync(path.join(SRC, "index.d.ts"), generateIndex(indexJs));
  console.log(
    `Generated .d.ts: ${models} models, ${apis} apis, ApiClient, index.`,
  );
}

main();
